func (q *Queries) SubscriptionByID(ctx context.Context, id uuid.UUID) (MobilitySubscription, error) {
	row := q.db.QueryRow(ctx, subscriptionByID, id)
	var i MobilitySubscription
	err := row.Scan(
		&i.ID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.StartsAt,
		&i.EndsAt,
		&i.SwapsUsed,
		&i.SwapsAllowance,
		&i.Status,
		&i.AutoRenew,
		&i.AccountID,
		&i.PlanID,
		&i.VehicleID,
		&i.AmountKobo,
		&i.DiscountCode,
		&i.DiscountKobo,
		&i.IdempotencyKey,
		&i.ListPriceKobo,
		&i.PaymentID,
		&i.QueuedPlanID,
	)
	return i, err
}
